self.KB_CONTENT["card:779687"]={"id":"card:779687","ty":"card","sourceId":"779687","title":"『MRP採購計劃發放作業』的作業目的為何？","ver":"GP4以上","topic":"採購單","keywords":["採購單","計劃","發放"],"y":"explain","answer":"可將已維護好之採購計劃內容，發放成為正式之採購單或請購單。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
