self.KB_CONTENT["card:826967"]={"id":"card:826967","ty":"card","sourceId":"826967","title":"結帳單無法修改稅別碼","ver":"GP4.0.1.0 以上","topic":"結帳單","keywords":["結帳單","稅別碼","單身","單頭"],"y":"error","answer":"結帳單身筆數>0，且單身其中一筆來源不等於9.其他時，單頭稅別碼欄位不可修改，為避免造成金額與來源單據不符。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
