self.KB_CONTENT["card:783475"]={"id":"card:783475","ty":"card","sourceId":"783475","title":"『新科目資料建立作業』中的『影響現金流量表項目 (MA023)』為何？","ver":"GP4以上","topic":"科目","keywords":["科目","分析"],"y":"other","answer":"* 該會計科目可自行指定其對應之現金流量表分析項目。* 可點選(icon)或按[F2]現金流量表項目查詢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
