self.KB_CONTENT["field:753294"]={"id":"field:753294","ty":"field","sourceId":"753294","title":"選擇類型","ver":"iGP","topic":"","keywords":[],"job":"單據指定不控管信用額度作業","code":"","answer":"* 不可空白。* 分為1.訂單、2.訂單變更單、3.銷貨單、4.出貨通知單及5.暫出單。* 修改時清除選擇單據資料。","file":"fields.jsonl"};
