self.KB_CONTENT["field:758710"]={"id":"field:758710","ty":"field","sourceId":"758710","title":"結帳碼","ver":"iGP","topic":"","keywords":[],"job":"進貨單建立作業","code":"TH031","answer":"* 顯示欄位，顯示該銷貨單是否已經產生對應的「應付憑單」（應付管理系統）。* 計有兩種狀態N.未結帳或Y.已結帳。","file":"fields.jsonl"};
self.KB_CONTENT["field:833653"]={"id":"field:833653","ty":"field","sourceId":"833653","title":"進貨日期","ver":"GP4.0.25.0以上","topic":"","keywords":[],"job":"進貨單建立作業","code":"","answer":"『進貨單建立作業-PURI09』的【單據日期】為單據新增輸入時輸入的日期，而【進貨日期】則是「進貨單」單身最後一筆【驗收日期】回寫的","file":"fields.jsonl"};
