self.KB_CONTENT["field:784900"]={"id":"field:784900","ty":"field","sourceId":"784900","title":"數量","ver":"GP4以上","topic":"","keywords":[],"job":"資產報廢建立作業","code":"TD005","answer":"* 可輸入報廢資產之數量。預設0。","file":"fields.jsonl"};
