self.KB_CONTENT["field:784269"]={"id":"field:784269","ty":"field","sourceId":"784269","title":"折畢續提耐用月數","ver":"GP4以上","topic":"","keywords":[],"job":"資產類別建立作業","code":"MA009","answer":"* 此項目為資產資料建立時之預設值，若各資產之續提耐用月數不同可不建立。","file":"fields.jsonl"};
