self.KB_CONTENT["field:752424"]={"id":"field:752424","ty":"field","sourceId":"752424","title":"欄位代號","ver":"iGP","topic":"","keywords":[],"job":"電子表單關聯建立作業","code":"MR004","answer":"* [F2]系統欄位資料查詢。* [F3]全部欄位資料查詢。* 不可空白且須存在於資料庫中。若存在者，則顯示欄位名稱，並預設檔案代號。","file":"fields.jsonl"};
